-- PostgreSQL initialization script. Runs automatically on first container initialization.
CREATE TABLE IF NOT EXISTS "Users" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" VARCHAR(100) NOT NULL,
    "Email" VARCHAR(255) NOT NULL,
    "Age" INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS "Products" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" VARCHAR(150) NOT NULL,
    "Price" NUMERIC(10,2) NOT NULL,
    "Description" VARCHAR(500) NULL
);

INSERT INTO "Users" ("Name", "Email", "Age")
SELECT seed."Name", seed."Email", seed."Age"
FROM (VALUES
    ('Alex', 'alex@example.com', 20),
    ('Maria', 'maria@example.com', 21),
    ('Ivan', 'ivan@example.com', 19)
) AS seed("Name", "Email", "Age")
WHERE NOT EXISTS (SELECT 1 FROM "Users");

INSERT INTO "Products" ("Name", "Price", "Description")
SELECT seed."Name", seed."Price", seed."Description"
FROM (VALUES
    ('Кофе', 250.00, 'Учебная запись'),
    ('Чай', 120.00, 'Учебная запись'),
    ('Кружка', 399.90, 'Учебная запись')
) AS seed("Name", "Price", "Description")
WHERE NOT EXISTS (SELECT 1 FROM "Products");
